<template>
 <div class="replacement-rounds"><el-alert title="按换出履约轮次保留计划和单据；主单只累计实际发出数量。已截停计划不会重复计入有效待发。" type="info" :closable="false" /><section v-for="r in rounds" :key="r.round_no" class="replacement-round"><div class="round-heading"><strong>第 {{ r.round_no }} 轮{{ r.round_no > 1 ? ' · 继续换出' : ' · 原换出履约' }}</strong><el-tag size="small" :type="r.state === 'REVIEW' || r.state === 'WAIT_STOCK' ? 'warning' : r.state === 'COMPLETED' ? 'success' : 'info'">{{ labels[r.state] || r.state }}</el-tag><span>{{ r.target_sku }} · 本轮计划 {{ r.quantity }} 件</span><span>实际发出 {{ shipped(r) }} 件 · 有效待发 {{ active(r) }} 件</span></div><p v-if="r.reason" class="muted">{{ r.reason }}<span v-if="r.reviewed_by"> · 审核 {{ r.reviewed_by }} / {{ r.review_reason }}</span></p><p v-if="r.state === 'REVIEW' || r.state === 'REJECTED'" class="muted">{{ r.state === 'REVIEW' ? '本轮尚未审核，未重新预占或生成发货单。' : '本次继续换出申请已拒绝，未建立新的库存需求。' }}</p><template v-else><p v-if="!ships(r).length" class="muted">{{ r.state === 'WAIT_STOCK' ? '换出库存不足，保留本轮数量；补货后继续核对原需求。' : '本轮尚无发货单，请按本轮进度完成预占和分仓。' }}</p><order-shipments v-else :order="order(r)" @changed="$emit('changed')" /></template></section></div>
</template>
<script>
import OrderShipments from './OrderShipments'
export default {components:{OrderShipments},props:{exchange:{type:Object,required:true}},data(){return {labels:{TERMINATED:'本轮已终止',REVIEW:'待继续换出审核',REJECTED:'申请已拒绝',APPROVED:'已审核，待预占 / 分仓',WAIT_STOCK:'等待换出库存',PROCESSING:'本轮换出处理中',COMPLETED:'本轮已完成'}}},computed:{rounds(){if((this.exchange.fulfillment_rounds||[]).length)return this.exchange.fulfillment_rounds;return [{round_no:1,quantity:this.exchange.requested_quantity,target_sku:this.exchange.target_sku,state:this.exchange.state==='CLOSED'?'TERMINATED':this.exchange.state==='COMPLETED'?'COMPLETED':this.exchange.state==='WAIT_STOCK'?'WAIT_STOCK':'PROCESSING'}]}},methods:{ships(r){return (this.exchange.shipments||[]).filter(s=>Number(s.fulfillment_round)===Number(r.round_no))},shipped(r){return this.ships(r).reduce((n,s)=>n+Number(s.shipped_quantity||0),0)},active(r){return this.ships(r).reduce((n,s)=>n+Math.max(0,Number(s.quantity)-Number(s.shipped_quantity||0)-Number(s.cancelled_quantity||0)),0)},order(r){const ships=this.ships(r);const current=Number(r.round_no)===Number(this.exchange.fulfillment_round);return {id:this.exchange.order_id,fulfillment_owner:'EXCHANGE',status:'WAIT_ALLOCATION',shipments:ships,allocation_quantity:current?this.exchange.allocation_quantity:0,pending_allocation_quantity:current?Math.max(0,Number(r.quantity)-Number(this.exchange.allocation_quantity||0)):0,shipped_quantity:this.shipped(r),shipment_count:ships.length,warehouse_accepted_quantity:ships.filter(s=>s.wms_dispatch_state==='ACCEPTED').reduce((n,s)=>n+Number(s.quantity),0)}}}}
</script>
<style scoped>.replacement-round{margin:18px 0;padding:18px 0;border-bottom:1px solid #e1e8f0}.round-heading{display:flex;gap:14px;align-items:center;flex-wrap:wrap;color:#3a506a}.muted{color:#8190a4;font-size:12px;line-height:1.8}</style>
